1	/**
2	 * Hono auth middleware backed by Better Auth.
3	 *
4	 * Replaces the Supabase-based `requireAuth` / `requireAdmin` /
5	 * `requireSuperAdmin` helpers from the original edge function's helpers.tsx.
6	 *
7	 * Usage in route modules:
8	 *   import { requireAuth, requireAdmin, requireSuperAdmin } from '@/server/middleware/auth';
9	 *
10	 *   router.use('/protected/*', requireAuth());
11	 *   router.get('/protected/data', (c) => {
12	 *     const user = c.get('authUser') as AuthUser;
13	 *     ...
14	 *   });
15	 */
16	
17	import { auth } from '@/lib/auth';
18	import { db } from '@/lib/db';
19	import {
20	  getE2eAuthBypassUser,
21	  hasValidE2eAuthBypassCookie,
22	} from '@/lib/e2e-auth-bypass';
23	import { safeErrorMessage as extractError } from '@/lib/safe-error-message';
24	import { authSession, authUser, superAdminRoleAssignments } from '@/lib/schema';
25	import { and, eq, gt } from 'drizzle-orm';
26	import type { Context, Next } from 'hono';
27	
28	import {
29	  type SuperAdminRole,
30	  getPermissionsForRole,
31	} from '@/components/features/mvp-v2/utils/super-admin-roles';
32	import type { SuperAdminRoleRow } from '@/lib/schema';
33	
34	/** Shape stored on Hono context after successful auth. */
35	export interface AuthUser {
36	  id: string;
37	  email: string;
38	  /** Platform role: 'user' | 'admin' | 'super_admin' */
39	  role: string;
40	  name?: string;
41	}
42	
43	/**
44	 * Convert a Hono `Context` request headers into a standard `Headers` object
45	 * that Better Auth's server-side API calls expect.
46	 *
47	 * @param c - The Hono request context.
48	 * @returns A standard `Headers` instance with all incoming request headers,
49	 *   including the session cookie forwarded to auth.api.* admin calls.
50	 */
51	export function honoToHeaders(c: Context): Headers {
52	  const headers = new Headers();
53	  c.req.raw.headers.forEach((value, key) => {
54	    headers.set(key, value);
55	  });
56	  return headers;
57	}
58	
59	type SessionLookupUser = {
60	  id: string;
61	  email: string;
62	  role?: string | null;
63	  name?: string | null;
64	};
65	
66	type SessionLookupResult = {
67	  user: SessionLookupUser;
68	  impersonatedBy: string | null;
69	};
70	
71	function parseCookieHeader(cookieHeader: string | null): Map<string, string> {
72	  const cookies = new Map<string, string>();
73	  if (!cookieHeader) return cookies;
74	
75	  for (const part of cookieHeader.split(';')) {
76	    const [rawName, ...rawValueParts] = part.trim().split('=');
77	    if (!rawName) continue;
78	
79	    const rawValue = rawValueParts.join('=');
80	    try {
81	      cookies.set(rawName, decodeURIComponent(rawValue));
82	    } catch {
83	      cookies.set(rawName, rawValue);
84	    }
85	  }
86	
87	  return cookies;
88	}
89	
90	function readSessionTokenCookieValue(value: string): string {
91	  return value.split('.')[0] ?? value;
92	}
93	
94	function getSessionTokenFromCookies(headers: Headers): string | null {
95	  const cookies = parseCookieHeader(headers.get('cookie'));
96	  const knownNames = [
97	    'better-auth.session_token',
98	    '__Secure-better-auth.session_token',
99	    'better-auth-session_token',
100	    '__Secure-better-auth-session_token',
101	    'session_token',
102	    '__Secure-session_token',
103	  ];
104	
105	  for (const name of knownNames) {
106	    const token = cookies.get(name);
107	    if (token) return readSessionTokenCookieValue(token);
108	  }
109	
110	  for (const [name, token] of cookies.entries()) {
111	    if (name.endsWith('.session_token') && token) {
112	      return readSessionTokenCookieValue(token);
113	    }
114	    if (name.endsWith('-session_token') && token) {
115	      return readSessionTokenCookieValue(token);
116	    }
117	  }
118	
119	  return null;
120	}
121	
122	async function findSessionByToken(
123	  token: string,
124	): Promise<SessionLookupResult | null> {
125	  const [row] = await db
126	    .select({
127	      session: authSession,
128	      user: authUser,
129	    })
130	    .from(authSession)
131	    .innerJoin(authUser, eq(authSession.userId, authUser.id))
132	    .where(
133	      and(eq(authSession.token, token), gt(authSession.expiresAt, new Date())),
134	    )
135	    .limit(1);
136	
137	  if (!row) return null;
138	
139	  const session = row.session as { impersonatedBy?: string | null };
140	  return {
141	    user: row.user as SessionLookupUser,
142	    impersonatedBy: session.impersonatedBy ?? null,
143	  };
144	}
145	
146	/**
147	 * Middleware factory that validates the Better Auth session and sets
148	 * `authUser` on the Hono context. Returns 401 on missing/invalid session.
149	 *
150	 * @param options.roles - If provided, restrict access to users with one of
151	 *   these roles. Returns 403 if the authenticated user's role is not included.
152	 */
153	export function requireAuth(options?: { roles?: string[] }) {
154	  return async (c: Context, next: Next): Promise<Response | undefined> => {
155	    try {
156	      const requestHeaders = honoToHeaders(c);
157	      const e2eBypassUser = getE2eAuthBypassUser(requestHeaders);
158	      if (e2eBypassUser) {
159	        if (
160	          options?.roles?.length &&
161	          !options.roles.includes(e2eBypassUser.role)
162	        ) {
163	          return c.json(
164	            {
165	              error: `Forbidden: requires one of [${options.roles.join(', ')}]`,
166	            },
167	            403,
168	          );
169	        }
170	
171	        c.set('authUser', {
172	          id: e2eBypassUser.id,
173	          email: e2eBypassUser.email,
174	          role: e2eBypassUser.role,
175	          name: e2eBypassUser.name,
176	        });
177	        await next();
178	        return;
179	      }
180	
181	      // 1. Try cookie-based auth (web clients)
182	      let user: SessionLookupUser | null = null;
183	      let impersonatedBy: string | null = null;
184	      try {
185	        const cookieSession = await auth.api.getSession({
186	          headers: requestHeaders,
187	        });
188	        user = cookieSession?.user ?? null;
189	
190	        // Native impersonation (Better Auth admin plugin): when set, the
191	        // session belongs to the impersonated user and `impersonatedBy` is the
192	        // admin's id. Exposed on context for audit/debug and used below to
193	        // reject the super-admin managed-school override during impersonation.
194	        impersonatedBy =
195	          (
196	            cookieSession?.session as
197	              | { impersonatedBy?: string | null }
198	              | undefined
199	          )?.impersonatedBy ?? null;
200	      } catch {
201	        user = null;
202	      }
203	
204	      // 2. Fallback: direct session-token DB lookup for web requests when
205	      // Better Auth's helper cannot resolve the session.
206	      if (!user) {
207	        const cookieToken = getSessionTokenFromCookies(requestHeaders);
208	        if (cookieToken) {
209	          const sessionLookup = await findSessionByToken(cookieToken);
210	          if (sessionLookup) {
211	            user = sessionLookup.user;
212	            impersonatedBy = sessionLookup.impersonatedBy;
213	          }
214	        }
215	      }
216	
217	      // 3. Fallback: Bearer token → direct DB lookup (mobile clients)
218	      if (!user) {
219	        const authHeader = c.req.header('authorization');
220	        if (authHeader?.startsWith('Bearer ')) {
221	          const sessionLookup = await findSessionByToken(authHeader.slice(7));
222	          if (sessionLookup) {
223	            user = sessionLookup.user;
224	            impersonatedBy = sessionLookup.impersonatedBy;
225	          }
226	        }
227	      }
228	
229	      if (!user) {
230	        return c.json({ error: 'Unauthorized: no valid session' }, 401);
231	      }
232	      if (impersonatedBy) c.set('impersonatedBy', impersonatedBy);
233	
234	      // 4. Ensure role is always fetched from database for accuracy.
235	      // Better Auth's getSession() may not include additionalFields (like role)
236	      // in the session response, OR may return the stale default 'user' role
237	      // when the user's role was promoted after session creation.
238	      // Re-verify from the auth_user table when role is missing or default.
239	      let role = user.role as string | null;
240	      if (!role || role === 'user') {
241	        const [dbUser] = await db
242	          .select({ role: authUser.role })
243	          .from(authUser)
244	          .where(eq(authUser.id, user.id))
245	          .limit(1);
246	        role = dbUser?.role ?? 'user';
247	      }
248	      role = role ?? 'user';
249	
250	      if (options?.roles && options.roles.length > 0) {
251	        if (!options.roles.includes(role)) {
252	          return c.json(
253	            {
254	              error: `Forbidden: requires one of [${options.roles.join(', ')}]`,
255	            },
256	            403,
257	          );
258	        }
259	      }
260	
261	      const authUser_: AuthUser = {
262	        id: user.id,
263	        email: user.email,
264	        role,
265	        name: user.name ?? undefined,
266	      };
267	
268	      c.set('authUser', authUser_);
269	
270	      // Super-admin managing a school: store the managed school ID on context
271	      // so resolveOrgIdFromSession can use it instead of the platform school.
272	      //
273	      // Precedence (design D-A): an active impersonation session always wins —
274	      // the impersonated user's own org is authoritative, so the client-supplied
275	      // X-Managed-School-Id header is ignored while impersonating. (In practice
276	      // admins can't be impersonated, so an impersonation session is never
277	      // super_admin; this is defense-in-depth.)
278	      if (authUser_.role === 'super_admin' && !impersonatedBy) {
279	        const managedSchoolId = c.req.header('x-managed-school-id');
280	        if (
281	          managedSchoolId &&
282	          /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
283	            managedSchoolId,
284	          )
285	        ) {
286	          c.set('managedSchoolId', managedSchoolId);
287	        }
288	      }
289	
290	      await next();
291	    } catch (err: unknown) {
292	      const message = extractError(err);
293	      return c.json({ error: `Authentication failed: ${message}` }, 500);
294	    }
295	  };
296	}
297	
298	/** Convenience: require `admin` or `super_admin` role. */
299	export function requireAdmin() {
300	  return requireAuth({ roles: ['admin', 'super_admin'] });
301	}
302	
303	/** Convenience: require `super_admin` role. */
304	export function requireSuperAdmin() {
305	  return requireAuth({ roles: ['super_admin'] });
306	}
307	
308	/**
309	 * Middleware factory that requires super_admin role AND a specific platform
310	 * permission. If the user has no role assignment, they are treated as
311	 * full-admin (all permissions granted — backward compatible).
312	 *
313	 * Must be used AFTER requireAuth/requireSuperAdmin in the middleware chain,
314	 * or it will check the role itself.
315	 *
316	 * @param permission - The `platform.*` permission key to require.
317	 * @param customRolesProvider - Optional async function to fetch custom roles
318	 *   from DB. If omitted, only built-in roles are checked.
319	 */
320	export function requirePlatformPermission(
321	  permission: string,
322	  customRolesProvider?: () => Promise<SuperAdminRoleRow[]>,
323	) {
324	  return async (c: Context, next: Next): Promise<Response | undefined> => {
325	    const authUser_ = c.get('authUser') as AuthUser | undefined;
326	    if (!authUser_ || authUser_.role !== 'super_admin') {
327	      return c.json({ error: 'Forbidden: requires super_admin role' }, 403);
328	    }
329	
330	    if (hasValidE2eAuthBypassCookie(honoToHeaders(c))) {
331	      await next();
332	      return;
333	    }
334	
335	    // Look up the user's role assignment
336	    const [assignment] = await db
337	      .select({ roleId: superAdminRoleAssignments.roleId })
338	      .from(superAdminRoleAssignments)
339	      .where(eq(superAdminRoleAssignments.userId, authUser_.id))
340	      .limit(1);
341	
342	    // No assignment → full-admin, allow everything
343	    if (!assignment) {
344	      await next();
345	      return;
346	    }
347	
348	    // Resolve the permissions for the assigned role
349	    let customRoles: SuperAdminRoleRow[] | undefined;
350	    if (customRolesProvider) {
351	      customRoles = await customRolesProvider();
352	    }
353	
354	    const rolePerms = getPermissionsForRole(
355	      assignment.roleId,
356	      customRoles?.map((r) => ({
357	        id: r.id,
358	        label: r.label,
359	        description: r.description ?? '',
360	        permissions: r.permissions as unknown as SuperAdminRole['permissions'],
361	        isCustom: true,
362	      })),
363	    );
364	
365	    if (!rolePerms.includes(permission as never)) {
366	      return c.json(
367	        { error: `Forbidden: missing platform permission '${permission}'` },
368	        403,
369	      );
370	    }
371	
372	    await next();
373	  };
374	}
