1	'use client';
2	
3	import { adminClient, inferAdditionalFields } from 'better-auth/client/plugins';
4	import { createAuthClient } from 'better-auth/react';
5	import type { auth } from './auth';
6	import { readClientE2eAuthUser } from './e2e-auth-bypass';
7	
8	/**
9	 * Resolves the auth base URL at runtime.
10	 *
11	 * Vercel exposes TWO different URLs per deployment:
12	 *   - Commit URL  (NEXT_PUBLIC_VERCEL_URL / VERCEL_URL) e.g. "app-abc123-org.vercel.app"
13	 *   - Branch alias e.g. "app-git-dev-org.vercel.app"
14	 *
15	 * If we hardcode either one, users visiting via the other alias get a CORS
16	 * error because the auth fetch crosses origins.
17	 *
18	 * In the browser: always use `window.location.origin` so auth requests are
19	 * always same-origin regardless of which alias the user landed on.
20	 *
21	 * On the server (SSR): resolve in priority order:
22	 *   1. NEXT_PUBLIC_VERCEL_URL — set if explicitly configured in the Vercel dashboard
23	 *   2. VERCEL_URL            — Vercel system variable, always available on the server
24	 *                              during SSR even though it is not exposed to the browser
25	 *   3. NEXT_PUBLIC_APP_URL   — explicit canonical URL (used for production builds)
26	 *   4. localhost fallback
27	 */
28	function resolveAuthBaseURL(): string {
29	  if (typeof window !== 'undefined') {
30	    return window.location.origin;
31	  }
32	  if (process.env.NEXT_PUBLIC_VERCEL_URL) {
33	    return `https://${process.env.NEXT_PUBLIC_VERCEL_URL}`;
34	  }
35	  // VERCEL_URL is a server-side system variable injected by Vercel for every
36	  // deployment. It is NOT exposed to the browser bundle, but this branch only
37	  // executes during SSR (window === undefined), so it is always available here.
38	  if (process.env.VERCEL_URL) {
39	    return `https://${process.env.VERCEL_URL}`;
40	  }
41	  return process.env.NEXT_PUBLIC_APP_URL ?? 'http://localhost:3000';
42	}
43	
44	const authBaseURL: string = resolveAuthBaseURL();
45	
46	/**
47	 * Better Auth Client
48	 *
49	 * Use this in client components for authentication operations.
50	 * `inferAdditionalFields` ensures the session user type includes
51	 * the `role` and `mustChangePassword` fields defined on the server.
52	 *
53	 * @example
54	 * ```tsx
55	 * import { authClient, useSession } from '@/lib/auth-client';
56	 *
57	 * // Sign in
58	 * await authClient.signIn.email({ email: 'user@example.com', password: 'password' });
59	 *
60	 * // Get session (use the hook in components)
61	 * const { data: session } = useSession();
62	 * console.log(session?.user.role);              // 'user' | 'admin' | 'super_admin'
63	 * console.log(session?.user.mustChangePassword); // boolean
64	 * ```
65	 */
66	export const authClient = createAuthClient({
67	  baseURL: authBaseURL,
68	  plugins: [
69	    // Propagates server-side additionalFields (role, mustChangePassword) into client types.
70	    inferAdditionalFields<typeof auth>(),
71	    // Native impersonation (admin plugin): exposes authClient.admin.impersonateUser /
72	    // stopImpersonating and types `session.impersonatedBy`. Server-side enabled in
73	    // src/lib/auth.ts. See docs/design/impersonation-remediation-design.md.
74	    adminClient(),
75	  ],
76	});
77	
78	let cachedE2eSession: {
79	  key: string;
80	  value: ReturnType<typeof authClient.useSession>;
81	} | null = null;
82	
83	/**
84	 * Hook to get current session in client components.
85	 * Replaces Supabase's useUser() hook.
86	 */
87	export function useSession() {
88	  const e2eUser = readClientE2eAuthUser();
89	  if (e2eUser) {
90	    const key = JSON.stringify(e2eUser);
91	    if (!cachedE2eSession || cachedE2eSession.key !== key) {
92	      const createdAt = new Date();
93	      const value = {
94	        data: {
95	          user: e2eUser,
96	          session: {
97	            id: 'e2e-session',
98	            token: 'e2e-session',
99	            userId: e2eUser.id,
100	            expiresAt: new Date(createdAt.getTime() + 60 * 60 * 1000),
101	            createdAt,
102	            updatedAt: createdAt,
103	          },
104	        },
105	        error: null,
106	        isPending: false,
107	        isRefetching: false,
108	        refetch: async () => undefined,
109	      } as unknown as ReturnType<typeof authClient.useSession>;
110	      cachedE2eSession = {
111	        key,
112	        value,
113	      };
114	    }
115	    const cached = cachedE2eSession;
116	    if (!cached) return authClient.useSession();
117	    return cached.value;
118	  }
119	
120	  return authClient.useSession();
121	}
