1	import { logAuthEvent } from '@/lib/audit';
2	import { auth } from '@/lib/auth';
3	import { db } from '@/lib/db';
4	import { safeErrorMessage } from '@/lib/safe-error-message';
5	import { authSession } from '@/lib/schema';
6	import * as Sentry from '@sentry/nextjs';
7	import { toNextJsHandler } from 'better-auth/next-js';
8	import { eq } from 'drizzle-orm';
9	import { type NextRequest, NextResponse } from 'next/server';
10	import { authSubEndpoint, extractIp } from './helpers';
11	
12	const { GET: _GET, POST: _POST } = toNextJsHandler(auth);
13	
14	function isDbConnectionError(error: unknown): boolean {
15	  const msg = safeErrorMessage(error);
16	  return (
17	    msg.includes('password authentication failed') ||
18	    msg.includes('ECONNREFUSED') ||
19	    msg.includes('connection refused') ||
20	    msg.includes('SASL') ||
21	    msg.includes('no pg_hba.conf entry') ||
22	    msg.includes('ETIMEDOUT') ||
23	    msg.includes('ECONNRESET') ||
24	    msg.includes('connect ENOENT')
25	  );
26	}
