28	/**
29	 * For sign-out: parse the `better-auth.session_token` cookie value and
30	 * look up the associated userId in the `session` table.
31	 * Returns null if the cookie is absent or the lookup fails.
32	 */
33	async function resolveSignOutUserId(req: NextRequest): Promise<string | null> {
34	  try {
35	    const cookieHeader = req.headers.get('cookie') ?? '';
36	    const match = cookieHeader.match(/better-auth\.session_token=([^;]+)/);
37	    if (!match) return null;
38	    const token = decodeURIComponent(match[1]);
39	    const rows = await db
40	      .select({ userId: authSession.userId })
41	      .from(authSession)
42	      .where(eq(authSession.token, token))
43	      .limit(1);
44	    return rows[0]?.userId ?? null;
45	  } catch {
46	    return null;
47	  }
48	}
