50	/**
51	 * Wraps a Better Auth handler with Sentry error capture.
52	 * DB connectivity failures are tagged as fatal (P0) since they
53	 * block all authentication and effectively take the site down.
54	 *
55	 * Also writes audit events for sign-in and sign-out requests.
56	 */
57	function withSentryAuthCapture(
58	  handler: (req: NextRequest) => Promise<Response>,
59	) {
60	  return async (req: NextRequest): Promise<Response> => {
61	    const pathname = req.nextUrl.pathname;
62	    const ipAddress = extractIp(req);
63	    const userAgent = req.headers.get('user-agent');
64	
65	    // Resolve sign-out userId BEFORE forwarding (session is deleted after)
66	    const isSignOut =
67	      req.method === 'POST' && pathname.endsWith('/api/auth/sign-out');
68	    const signOutUserId = isSignOut ? await resolveSignOutUserId(req) : null;
69	
70	    try {
71	      const response = await handler(req);
72	
73	      // --- Sign-in audit ---
74	      if (
75	        req.method === 'POST' &&
76	        pathname.endsWith('/api/auth/sign-in/email')
77	      ) {
78	        try {
79	          const cloned = response.clone();
80	          const body = await cloned.json().catch(() => null);
81	          if (response.ok && body?.user?.id) {
82	            void logAuthEvent({
83	              actorUserId: body.user.id,
84	              eventType: 'signin',
85	              success: true,
86	              ipAddress,
87	              userAgent,
88	            });
89	          } else if (!response.ok) {
90	            void logAuthEvent({
91	              eventType: 'signin',
92	              success: false,
93	              errorCode: String(response.status),
94	              ipAddress,
95	              userAgent,
96	            });
97	          }
98	        } catch {
99	          // audit path must never throw
100	        }
101	      }
102	
103	      // --- Sign-out audit ---
104	      if (isSignOut) {
105	        try {
106	          void logAuthEvent({
107	            actorUserId: signOutUserId ?? null,
108	            eventType: 'signout',
109	            success: response.ok,
110	            errorCode: response.ok ? null : String(response.status),
111	            ipAddress,
112	            userAgent,
113	          });
114	        } catch {
115	          // audit path must never throw
116	        }
117	      }
118	
119	      return response;
120	    } catch (error) {
121	      const isDbError = isDbConnectionError(error);
122	      const subEndpoint = authSubEndpoint(pathname);
123	
124	      Sentry.withScope((scope) => {
125	        scope.setLevel(isDbError ? 'fatal' : 'error');
126	        scope.setTags({
127	          'auth.endpoint': pathname,
128	          'auth.sub_endpoint': subEndpoint,
129	          'auth.method': req.method,
130	          'auth.db_failure': isDbError,
131	        });
132	        scope.setContext('auth', {
133	          endpoint: pathname,
134	          sub_endpoint: subEndpoint,
135	          method: req.method,
136	          db_failure: isDbError,
137	        });
138	        // Group per (method, sub-endpoint) so distinct auth endpoints don't
139	        // collapse into a single opaque `/:all*` issue. Without this, a
140	        // TypeError in sign-in and a DB failure in sign-out share one Sentry
141	        // issue, making each occurrence harder to diagnose.
142	        scope.setFingerprint([
143	          'api.auth.catchall',
144	          req.method,
145	          subEndpoint,
146	          isDbError ? 'db_failure' : 'error',
147	        ]);
148	        Sentry.captureException(error);
149	      });
150	
151	      if (isDbError) {
152	        console.error(
153	          '[Auth P0] Database connectivity failure on',
154	          pathname,
155	          ':',
156	          safeErrorMessage(error),
157	        );
158	      }
159	
160	      // Write failed sign-in audit on thrown errors too
161	      if (
162	        req.method === 'POST' &&
163	        pathname.endsWith('/api/auth/sign-in/email')
164	      ) {
165	        try {
166	          void logAuthEvent({
167	            eventType: 'signin',
168	            success: false,
169	            errorCode: '500',
170	            ipAddress,
171	            userAgent,
172	          });
173	        } catch {
174	          // audit path must never throw
175	        }
176	      }
177	
178	      return NextResponse.json(
179	        { error: 'Internal server error' },
180	        { status: 500 },
181	      );
182	    }
183	  };
184	}
