1	import type { NextRequest } from 'next/server';
2	
3	const AUTH_ROUTE_PREFIX = '/api/auth/';
4	
5	/**
6	 * Extract the caller's IP from standard proxy headers.
7	 */
8	export function extractIp(req: NextRequest): string | null {
9	  // Defensive optional chaining matches the pattern used everywhere else in
10	  // the codebase (routes-agreements.ts, server/api/v1/lib/*.ts). Without it,
11	  // `[0]` is typed as `string` by tsc (noUncheckedIndexedAccess is off) but
12	  // can be undefined at runtime for pathological header values, producing
13	  // `TypeError: Cannot read properties of undefined (reading 'trim')` on the
14	  // Sentry catchall `/:all*` transaction. See PR #3489.
15	  const first = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim();
16	  if (first) return first;
17	
18	  // Also trim x-real-ip — a whitespace-only header would otherwise be
19	  // returned verbatim and surface downstream as an invalid IP string.
20	  const real = req.headers.get('x-real-ip')?.trim();
21	  return real && real.length > 0 ? real : null;
22	}
23	
24	/**
25	 * Better Auth sub-endpoint extracted from the request path, for Sentry
26	 * fingerprinting. Returns the part after `/api/auth/` (e.g. `sign-in/email`)
27	 * or `unknown` if the path does not contain that prefix.
28	 */
29	export function authSubEndpoint(pathname: string): string {
30	  const idx = pathname.indexOf(AUTH_ROUTE_PREFIX);
31	  if (idx === -1) return 'unknown';
32	  const tail = pathname.slice(idx + AUTH_ROUTE_PREFIX.length);
33	  return tail.length > 0 ? tail : 'root';
34	}
