226	/**
227	 * Resolves the flight school used to brand an invite / credential email.
228	 *
229	 * Super admins operate across schools, so when they explicitly target a school
230	 * (`schoolId` from the request body) the email is branded with THAT school.
231	 * Everyone else — and super admins who did not supply a valid school — falls
232	 * back to the caller's own school, preserving the original behavior.
233	 *
234	 * Defect-A fix: previously the school was ALWAYS derived from the caller, so a
235	 * super admin inviting into school B received an email branded for their own
236	 * school A (and the choice was non-deterministic). See
237	 * rca/admin-invite-cross-school.md.
238	 */
239	type InviteSchoolBranding =
240	  | { ok: true; schoolName: string | undefined; flightSchoolId: string | null }
241	  | { ok: false; reason: 'school_not_found' };
242	
243	async function resolveInviteSchoolBranding(
244	  caller: AuthUser | undefined,
245	  requestedSchoolId: unknown,
246	): Promise<InviteSchoolBranding> {
247	  const bodySchoolId =
248	    typeof requestedSchoolId === 'string' && requestedSchoolId.trim()
249	      ? requestedSchoolId.trim()
250	      : undefined;
251	
252	  // Super admin explicitly targeting a school: the school MUST resolve to a real
253	  // record. If a schoolId was supplied but is malformed or does not exist, we
254	  // must NOT fall back to the caller's own school — that would re-introduce the
255	  // exact cross-school disclosure/mislabel this helper exists to prevent. Signal
256	  // not-found so the handler can return a hard, actionable error. (Defect-A fix.)
257	  if (caller?.role === 'super_admin' && bodySchoolId) {
258	    if (!isUuid(bodySchoolId)) {
259	      return { ok: false, reason: 'school_not_found' };
260	    }
261	    const [school] = await db
262	      .select({
263	        id: schema.flightSchools.id,
264	        name: schema.flightSchools.name,
265	      })
266	      .from(schema.flightSchools)
267	      .where(eq(schema.flightSchools.id, bodySchoolId))
268	      .limit(1);
269	    if (!school) {
270	      return { ok: false, reason: 'school_not_found' };
271	    }
272	    return { ok: true, schoolName: school.name, flightSchoolId: school.id };
273	  }
274	
275	  // Fallback: the caller's own school (regular admins, or a super admin who did
276	  // not target a specific school). Non-fatal — undefined branding is acceptable
277	  // (the template uses neutral "your flight school" / HILO copy).
278	  if (caller?.email) {
279	    const { mvpRepository } = await import(
280	      '@/repositories/mvp-v2.repository.impl'
281	    );
282	    const appUser = await mvpRepository.users
283	      .findByEmailGlobal(caller.email)
284	      .catch(() => null);
285	    return {
286	      ok: true,
287	      schoolName: appUser?.orgName ?? undefined,
288	      flightSchoolId: appUser?.flightSchoolId ?? null,
289	    };
290	  }
291	
292	  return { ok: true, schoolName: undefined, flightSchoolId: null };
293	}
