1	/**
2	 * `/api/oauth/authorize` handler logic.
3	 *
4	 * The route boundary in `src/app/api/oauth/authorize/route.ts` parses the
5	 * request, builds an `OAuthStore`, and resolves the BetterAuth session;
6	 * everything else lives here so the flow can be unit-tested without a
7	 * Next.js request object.
8	 *
9	 * Flow (RFC 6749 §4.1, RFC 7636):
10	 *   1. Feature flag gate
11	 *   2. Static query validation (response_type, code_challenge_method)
12	 *   3. Client + redirect_uri + scope validation
13	 *   4. Authentication check — redirect to login if no session
14	 *   5. GET → render consent screen
15	 *   6. POST approve → mint authorization code + 302 to client redirect_uri
16	 *   7. POST deny    → 302 to client redirect_uri with access_denied
17	 */
18	
19	import { requireIntegrationApiEnabled } from '@/server/integrations/zapier/feature-flag';
20	import { generateAuthorizationCode } from './crypto';
21	import { OAuthError } from './errors';
22	import { isSupportedChallengeMethod, isValidCodeChallenge } from './pkce';
23	import { InvalidScopeError, isAllowedSubset, parseScopeString } from './scopes';
24	import type { OAuthStore, UserAndSchool } from './store';
25	import { AUTHORIZATION_CODE_TTL_SECONDS, type OAuthScope } from './types';
26	
27	export interface AuthorizeQuery {
28	  response_type?: string;
29	  client_id?: string;
30	  redirect_uri?: string;
31	  scope?: string;
32	  state?: string;
33	  code_challenge?: string;
34	  code_challenge_method?: string;
35	}
36	
37	export interface ValidatedAuthorize {
38	  clientId: string;
39	  clientName: string;
40	  redirectUri: string;
41	  scopes: OAuthScope[];
42	  state: string;
43	  codeChallenge: string;
44	}
45	
46	export interface AuthorizeSession {
47	  /** Email of the logged-in BetterAuth user; resolved server-side. */
48	  email: string;
49	}
50	
51	export type AuthorizeGetResult =
52	  | { kind: 'consent'; validated: ValidatedAuthorize; user: UserAndSchool }
53	  | { kind: 'redirect-to-login'; returnTo: string }
54	  | { kind: 'error'; error: OAuthError };
55	
56	export type AuthorizePostResult =
57	  | { kind: 'approved'; redirectTo: string }
58	  | { kind: 'denied'; redirectTo: string }
59	  | { kind: 'error'; error: OAuthError };
60	
61	export interface AuthorizeGetArgs {
62	  query: AuthorizeQuery;
63	  session: AuthorizeSession | null;
64	  store: OAuthStore;
65	  /** Full original URL ("/api/oauth/authorize?...") for the login returnTo. */
66	  fullUrl: string;
67	}
68	
69	export interface AuthorizePostArgs {
70	  query: AuthorizeQuery;
71	  action: 'approve' | 'deny';
72	  session: AuthorizeSession | null;
73	  store: OAuthStore;
74	  now?: () => Date;
75	}
76	
77	/**
78	 * GET /api/oauth/authorize — validate params, then either render consent or
79	 * redirect to login. Throws nothing; result kind tells the caller what to do.
80	 */
81	export async function handleAuthorizeGet(
82	  args: AuthorizeGetArgs,
83	): Promise<AuthorizeGetResult> {
84	  requireIntegrationApiEnabled();
85	
86	  let validated: ValidatedAuthorize;
87	  try {
88	    validated = await validate(args.query, args.store);
89	  } catch (err) {
90	    if (err instanceof OAuthError) return { kind: 'error', error: err };
91	    throw err;
92	  }
93	
94	  if (!args.session) {
95	    return { kind: 'redirect-to-login', returnTo: args.fullUrl };
96	  }
97	
98	  const user = await args.store.resolveAppUserFromAuthEmail(args.session.email);
99	  if (!user) {
100	    return {
101	      kind: 'error',
102	      error: new OAuthError(
103	        'access_denied',
104	        'authenticated session has no app user record',
105	      ),
106	    };
107	  }
108	
109	  return { kind: 'consent', validated, user };
110	}
111	
112	/**
113	 * POST /api/oauth/authorize — handle the user's Approve / Deny click from
114	 * the consent screen.
115	 */
116	export async function handleAuthorizePost(
117	  args: AuthorizePostArgs,
118	): Promise<AuthorizePostResult> {
119	  requireIntegrationApiEnabled();
120	
121	  let validated: ValidatedAuthorize;
122	  try {
123	    validated = await validate(args.query, args.store);
124	  } catch (err) {
125	    if (err instanceof OAuthError) return { kind: 'error', error: err };
126	    throw err;
127	  }
128	
129	  if (!args.session) {
130	    return {
131	      kind: 'error',
132	      error: new OAuthError('access_denied', 'no authenticated session'),
133	    };
134	  }
135	
136	  if (args.action === 'deny') {
137	    return {
138	      kind: 'denied',
139	      redirectTo: buildClientRedirect(validated.redirectUri, {
140	        error: 'access_denied',
141	        state: validated.state,
142	      }),
143	    };
144	  }
145	
146	  const user = await args.store.resolveAppUserFromAuthEmail(args.session.email);
147	  if (!user) {
148	    return {
149	      kind: 'error',
150	      error: new OAuthError('access_denied', 'no app user record'),
151	    };
152	  }
153	
154	  const now = (args.now ?? (() => new Date()))();
155	  const code = generateAuthorizationCode();
156	
157	  await args.store.insertAuthorizationCode({
158	    codeHash: code.hash,
159	    clientId: validated.clientId,
160	    userId: user.userId,
161	    flightSchoolId: user.flightSchoolId,
162	    redirectUri: validated.redirectUri,
163	    scopes: validated.scopes,
164	    codeChallenge: validated.codeChallenge,
165	    expiresAt: new Date(now.getTime() + AUTHORIZATION_CODE_TTL_SECONDS * 1000),
166	  });
167	
168	  return {
169	    kind: 'approved',
170	    redirectTo: buildClientRedirect(validated.redirectUri, {
171	      code: code.plaintext,
172	      state: validated.state,
173	    }),
174	  };
175	}
176	
177	async function validate(
178	  query: AuthorizeQuery,
179	  store: OAuthStore,
180	): Promise<ValidatedAuthorize> {
181	  if (query.response_type !== 'code') {
182	    throw new OAuthError('invalid_request', 'response_type must be "code"');
183	  }
184	  const clientId = requireField(query, 'client_id');
185	  const redirectUri = requireField(query, 'redirect_uri');
186	  const scope = requireField(query, 'scope');
187	  const state = requireField(query, 'state');
188	  const codeChallenge = requireField(query, 'code_challenge');
189	  const method = requireField(query, 'code_challenge_method');
190	
191	  if (!isSupportedChallengeMethod(method)) {
192	    throw new OAuthError(
193	      'invalid_request',
194	      'code_challenge_method must be S256',
195	    );
196	  }
197	  if (!isValidCodeChallenge(codeChallenge)) {
198	    throw new OAuthError('invalid_request', 'code_challenge is malformed');
199	  }
200	
201	  const client = await store.findClientByClientId(clientId);
202	  if (!client || client.revokedAt) {
203	    throw new OAuthError('invalid_request', 'unknown or revoked client');
204	  }
205	
206	  if (!client.redirectUris.includes(redirectUri)) {
207	    throw new OAuthError('invalid_request', 'redirect_uri not registered');
208	  }
209	
210	  let parsed: OAuthScope[];
211	  try {
212	    parsed = parseScopeString(scope);
213	  } catch (err) {
214	    if (err instanceof InvalidScopeError) {
215	      throw new OAuthError('invalid_scope', err.message);
216	    }
217	    throw err;
218	  }
219	  if (!isAllowedSubset(parsed, client.allowedScopes)) {
220	    throw new OAuthError(
221	      'invalid_scope',
222	      'requested scope exceeds client allowed_scopes',
223	    );
224	  }
225	
226	  return {
227	    clientId,
228	    clientName: client.clientName,
229	    redirectUri,
230	    scopes: parsed,
231	    state,
232	    codeChallenge,
233	  };
234	}
235	
236	function requireField<K extends keyof AuthorizeQuery>(
237	  query: AuthorizeQuery,
238	  key: K,
239	): string {
240	  const value = query[key];
241	  if (typeof value !== 'string' || value.length === 0) {
242	    throw new OAuthError('invalid_request', `missing ${String(key)}`);
243	  }
244	  return value;
245	}
246	
247	function buildClientRedirect(
248	  base: string,
249	  params: Record<string, string>,
250	): string {
251	  // RFC 6749 §4.1.2 — append to existing query string if present.
252	  const sep = base.includes('?') ? '&' : '?';
253	  const qs = Object.entries(params)
254	    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
255	    .join('&');
256	  return `${base}${sep}${qs}`;
257	}
