1	/**
2	 * `/api/oauth/token` handler logic.
3	 *
4	 * Handles both the `authorization_code` grant (RFC 6749 §4.1.3) and the
5	 * `refresh_token` grant (§6). Client credentials come from the HTTP Basic
6	 * `Authorization` header; the route boundary decodes it and passes
7	 * `clientId` + `clientSecret` here.
8	 *
9	 * Errors come back as `OAuthError` so the route can serialize to the RFC
10	 * 6749 §5.2 JSON envelope (`{ error, error_description }`).
11	 */
12	
13	import { requireIntegrationApiEnabled } from '@/server/integrations/zapier/feature-flag';
14	import * as Sentry from '@sentry/nextjs';
15	import { constantTimeEquals, sha256, verifyClientSecret } from './crypto';
16	import { OAuthError } from './errors';
17	import { verifyPkceS256 } from './pkce';
18	import { type OAuthScope, formatScopeString } from './scopes';
19	import type { OAuthStore } from './store';
20	import { mintTokenPair } from './token-issue';
21	import { REFRESH_ROTATION_GRACE_SECONDS } from './types';
22	
23	export interface ClientCredentials {
24	  clientId: string;
25	  clientSecret: string;
26	}
27	
28	export type GrantType = 'authorization_code' | 'refresh_token';
29	
30	export interface AuthorizationCodeBody {
31	  grant_type: 'authorization_code';
32	  code: string;
33	  redirect_uri: string;
34	  code_verifier: string;
35	}
36	
37	export interface RefreshTokenBody {
38	  grant_type: 'refresh_token';
39	  refresh_token: string;
40	}
41	
42	export type TokenBody = AuthorizationCodeBody | RefreshTokenBody;
43	
44	export interface TokenSuccess {
45	  access_token: string;
46	  token_type: 'Bearer';
47	  expires_in: number;
48	  refresh_token: string;
49	  scope: string;
50	}
51	
52	export interface HandleTokenArgs {
53	  credentials: ClientCredentials | null;
54	  body: Record<string, string | undefined>;
55	  store: OAuthStore;
56	  now?: () => Date;
57	}
58	
59	export type TokenResult =
60	  | { kind: 'success'; response: TokenSuccess }
61	  | { kind: 'error'; error: OAuthError };
62	
63	export async function handleToken(args: HandleTokenArgs): Promise<TokenResult> {
64	  requireIntegrationApiEnabled();
65	
66	  try {
67	    if (!args.credentials) {
68	      throw new OAuthError(
69	        'invalid_client',
70	        'missing or malformed Authorization header',
71	      );
72	    }
73	
74	    const client = await args.store.findClientByClientId(
75	      args.credentials.clientId,
76	    );
77	    if (!client || client.revokedAt) {
78	      throw new OAuthError('invalid_client', 'unknown or revoked client');
79	    }
80	    const secretOk = await verifyClientSecret(
81	      args.credentials.clientSecret,
82	      client.clientSecretHash,
83	    );
84	    if (!secretOk) {
85	      throw new OAuthError('invalid_client', 'client authentication failed');
86	    }
87	
88	    const grantType = args.body.grant_type;
89	    if (grantType === 'authorization_code') {
90	      return await handleAuthorizationCodeGrant({
91	        ...args,
92	        clientId: args.credentials.clientId,
93	      });
94	    }
95	    if (grantType === 'refresh_token') {
96	      return await handleRefreshTokenGrant({
97	        ...args,
98	        clientId: args.credentials.clientId,
99	      });
100	    }
101	    throw new OAuthError(
102	      'unsupported_grant_type',
103	      `grant_type "${grantType ?? ''}" is not supported`,
104	    );
105	  } catch (err) {
106	    if (err instanceof OAuthError) return { kind: 'error', error: err };
107	    throw err;
108	  }
109	}
110	
111	async function handleAuthorizationCodeGrant(args: {
112	  body: Record<string, string | undefined>;
113	  store: OAuthStore;
114	  clientId: string;
115	  now?: () => Date;
116	}): Promise<TokenResult> {
117	  const code = requireField(args.body, 'code');
118	  const redirectUri = requireField(args.body, 'redirect_uri');
119	  const codeVerifier = requireField(args.body, 'code_verifier');
120	
121	  const now = (args.now ?? (() => new Date()))();
122	  const hash = sha256(code);
123	  const codeRow = await args.store.findAuthorizationCodeByHash(hash);
124	  if (!codeRow) {
125	    throw new OAuthError('invalid_grant', 'authorization code not found');
126	  }
127	  if (codeRow.usedAt) {
128	    throw new OAuthError('invalid_grant', 'authorization code already used');
129	  }
130	  if (codeRow.expiresAt.getTime() <= now.getTime()) {
131	    throw new OAuthError('invalid_grant', 'authorization code expired');
132	  }
133	  if (codeRow.clientId !== args.clientId) {
134	    throw new OAuthError(
135	      'invalid_grant',
136	      'authorization code issued to a different client',
137	    );
138	  }
139	  if (codeRow.redirectUri !== redirectUri) {
140	    throw new OAuthError('invalid_grant', 'redirect_uri mismatch');
141	  }
142	  if (!verifyPkceS256(codeVerifier, codeRow.codeChallenge)) {
143	    throw new OAuthError('invalid_grant', 'PKCE verifier mismatch');
144	  }
145	
146	  // Single-use: mark consumed BEFORE issuing tokens. If the mint step fails,
147	  // the code is still burned — which is the safer failure mode (no replay).
148	  await args.store.markAuthorizationCodeUsed(codeRow.id);
149	
150	  const minted = await mintTokenPair({
151	    store: args.store,
152	    clientId: args.clientId,
153	    userId: codeRow.userId,
154	    flightSchoolId: codeRow.flightSchoolId,
155	    scopes: codeRow.scopes,
156	    now: args.now,
157	  });
158	
159	  // Supersede-on-reconnect: a re-authorization mints a fresh 30-day refresh
160	  // token, so revoke the prior LIVE ones for this (client_id, flight_school_id)
161	  // to stop orphaned refresh credentials from piling up across reconnects.
162	  // Best-effort and AFTER the mint — this must NEVER fail the grant. If the
163	  // revoke throws, the client still gets its valid token; the leftovers are
164	  // reaped by the next reconnect or 30-day expiry. Bounded by the new token's
165	  // own created_at (strict `<`) so concurrent reconnects can't revoke each
166	  // other's freshly minted token. Within-chain rotation (refresh_token grant)
167	  // is deliberately untouched — this fires ONLY on authorization_code.
168	  try {
169	    await args.store.revokePriorRefreshTokens({
170	      clientId: args.clientId,
171	      flightSchoolId: codeRow.flightSchoolId,
172	      createdBefore: minted.refreshCreatedAt,
173	    });
174	  } catch (err) {
175	    Sentry.captureException(err, {
176	      level: 'warning',
177	      tags: {
178	        oauth_supersede: 'revoke_prior_failed',
179	        oauth_client_id: args.clientId,
180	        oauth_flight_school_id: codeRow.flightSchoolId,
181	      },
182	    });
183	  }
184	
185	  return {
186	    kind: 'success',
187	    response: {
188	      access_token: minted.accessToken,
189	      token_type: 'Bearer',
190	      expires_in: minted.expiresIn,
191	      refresh_token: minted.refreshToken,
192	      scope: formatScopeString(codeRow.scopes),
193	    },
194	  };
195	}
196	
197	async function handleRefreshTokenGrant(args: {
198	  body: Record<string, string | undefined>;
199	  store: OAuthStore;
200	  clientId: string;
201	  now?: () => Date;
202	}): Promise<TokenResult> {
203	  const refresh = requireField(args.body, 'refresh_token');
204	  const now = (args.now ?? (() => new Date()))();
205	
206	  const hash = sha256(refresh);
207	  const row = await args.store.findRefreshTokenByHash(hash);
208	  if (!row) {
209	    throw new OAuthError('invalid_grant', 'refresh token not found');
210	  }
211	  // Reuse of an already-rotated token. Within the grace window this is a
212	  // benign concurrency race (Zapier polls one connection from several
213	  // independent workers, so two refreshes can race on the same token) and
214	  // we mint a sibling pair below WITHOUT re-rotating. Beyond the window it
215	  // is a replay — RFC 6749 §10.4 recommends revoking the chain, so we
216	  // revoke the access token issued on it and reject. Check `rotatedTo`
217	  // BEFORE the plain-revoked check: rotation also sets `revokedAt` (that
218	  // timestamp IS the rotation time), but a true replay needs to surface as
219	  // "rotated" so the caller (and the audit log) can see the attack pattern.
220	  const rotatedAt = row.rotatedTo ? row.revokedAt : null;
221	  const withinRotationGrace =
222	    rotatedAt !== null &&
223	    now.getTime() - rotatedAt.getTime() <=
224	      REFRESH_ROTATION_GRACE_SECONDS * 1000;
225	  if (row.rotatedTo && !withinRotationGrace) {
226	    await args.store.revokeAccessTokensForRefreshChain(row.id);
227	    throw new OAuthError('invalid_grant', 'refresh token already rotated');
228	  }
229	  if (!row.rotatedTo && row.revokedAt) {
230	    throw new OAuthError('invalid_grant', 'refresh token revoked');
231	  }
232	  if (row.expiresAt.getTime() <= now.getTime()) {
233	    throw new OAuthError('invalid_grant', 'refresh token expired');
234	  }
235	  if (row.clientId !== args.clientId) {
236	    throw new OAuthError(
237	      'invalid_grant',
238	      'refresh token issued to a different client',
239	    );
240	  }
241	
242	  const minted = await mintTokenPair({
243	    store: args.store,
244	    clientId: args.clientId,
245	    userId: row.userId,
246	    flightSchoolId: row.flightSchoolId,
247	    scopes: row.scopes as OAuthScope[],
248	    now: args.now,
249	  });
250	
251	  if (!row.rotatedTo) {
252	    // `false` means a concurrent refresh claimed the rotation between our
253	    // read and this write — the same benign race as the grace branch, so
254	    // both minted pairs stay valid and the row keeps its first successor.
255	    await args.store.rotateRefreshToken(row.id, minted.refreshTokenId);
256	  }
257	  // Grace-window replays skip rotation entirely: the row's `rotatedTo`
258	  // keeps pointing at the first successor, and strict replay revocation
259	  // resumes once the window closes.
260	
261	  return {
262	    kind: 'success',
263	    response: {
264	      access_token: minted.accessToken,
265	      token_type: 'Bearer',
266	      expires_in: minted.expiresIn,
267	      refresh_token: minted.refreshToken,
268	      scope: formatScopeString(row.scopes as OAuthScope[]),
269	    },
270	  };
271	}
272	
273	function requireField(
274	  body: Record<string, string | undefined>,
275	  key: string,
276	): string {
277	  const value = body[key];
278	  if (typeof value !== 'string' || value.length === 0) {
279	    throw new OAuthError('invalid_request', `missing ${key}`);
280	  }
281	  return value;
282	}
283	
284	/**
285	 * Parse the HTTP Basic `Authorization` header (RFC 7617). Returns `null` on
286	 * any malformed input — the caller maps that to `invalid_client`. Uses a
287	 * constant-time-style check for the "Basic " prefix to avoid trivial timing
288	 * differences across requests; the credential bytes themselves still surface
289	 * through argon2's own constant-time path.
290	 */
291	export function parseBasicAuthHeader(
292	  header: string | null | undefined,
293	): ClientCredentials | null {
294	  if (!header) return null;
295	  const prefix = 'Basic ';
296	  if (header.length <= prefix.length) return null;
297	  const headerPrefix = header.slice(0, prefix.length);
298	  // Header prefix is case-sensitive per RFC 7617 §2.
299	  if (!constantTimeEquals(headerPrefix, prefix)) return null;
300	  const encoded = header.slice(prefix.length).trim();
301	  let decoded: string;
302	  try {
303	    decoded = Buffer.from(encoded, 'base64').toString('utf8');
304	  } catch {
305	    return null;
306	  }
307	  const idx = decoded.indexOf(':');
308	  if (idx < 0) return null;
309	  const clientId = decoded.slice(0, idx);
310	  const clientSecret = decoded.slice(idx + 1);
311	  if (!clientId || !clientSecret) return null;
312	  return { clientId, clientSecret };
313	}
