1	/**
2	 * Crypto helpers for the Zapier OAuth surface.
3	 *
4	 * - Bearer / refresh / authorization-code values are random bytes; we persist
5	 *   their SHA-256 hash and compare in constant time at lookup. The plaintext
6	 *   value is only ever returned once to the caller and never logged.
7	 * - Client secrets are persisted as `argon2id(secret || pepper)`. The pepper
8	 *   lives in `OAUTH_CLIENT_SECRET_PEPPER` (never in the DB) so a stolen DB
9	 *   dump alone is insufficient to brute-force.
10	 *
11	 * argon2 is a native dependency listed in `prompts/zapier-wave-1/dependency-map.md`
12	 * (Wave 1 §"New runtime dependencies"). It is imported dynamically so this
13	 * module loads cleanly in environments where the native build is unavailable
14	 * (e.g. early CI / lint-only stages); callers that touch argon2 surface a
15	 * clear runtime error.
16	 */
17	
18	import { createHash, randomBytes, timingSafeEqual } from 'node:crypto';
19	
20	import { AUTHORIZATION_CODE_BYTES, TOKEN_BYTES } from './types';
21	
22	// ─── Constants ──────────────────────────────────────────────────────────────
23	
24	const PEPPER_ENV_VAR = 'OAUTH_CLIENT_SECRET_PEPPER';
25	
26	/**
27	 * argon2id parameters chosen per OWASP "Password Storage Cheat Sheet"
28	 * (m=64 MiB, t=3, p=4). Client secrets are high-entropy random bytes, so we
29	 * do not need extreme work factors — these defaults are a comfortable margin
30	 * over OWASP minimum.
31	 */
32	export const ARGON2_PARAMS = {
33	  type: 2 /* argon2id; mirrors argon2.argon2id without importing the dep here */,
34	  memoryCost: 64 * 1024,
35	  timeCost: 3,
36	  parallelism: 4,
37	} as const;
38	
39	// ─── SHA-256 + token generation ─────────────────────────────────────────────
40	
41	/** base64url encode without padding (RFC 4648 §5). */
42	function base64url(buf: Buffer): string {
43	  return buf
44	    .toString('base64')
45	    .replace(/\+/g, '-')
46	    .replace(/\//g, '_')
47	    .replace(/=+$/, '');
48	}
49	
50	/** SHA-256 of a UTF-8 string, base64url encoded. */
51	export function sha256(value: string): string {
52	  return base64url(createHash('sha256').update(value, 'utf8').digest());
53	}
54	
55	/**
56	 * Generate a high-entropy random bearer / refresh token.
57	 * Returns the plaintext value (base64url) and its SHA-256 hash.
58	 * Persist only the hash; return the plaintext to the caller exactly once.
59	 */
60	export function generateOpaqueToken(byteLength: number = TOKEN_BYTES): {
61	  plaintext: string;
62	  hash: string;
63	} {
64	  const plaintext = base64url(randomBytes(byteLength));
65	  return { plaintext, hash: sha256(plaintext) };
66	}
67	
68	/**
69	 * Generate a single-use authorization code.
70	 * Same shape as `generateOpaqueToken`; uses 32 bytes per spec.
71	 */
72	export function generateAuthorizationCode(): {
73	  plaintext: string;
74	  hash: string;
75	} {
76	  return generateOpaqueToken(AUTHORIZATION_CODE_BYTES);
77	}
78	
79	/**
80	 * Constant-time comparison of two SHA-256 hashes (base64url strings).
81	 * Returns false on any length / format mismatch without throwing.
82	 */
83	export function constantTimeEquals(a: string, b: string): boolean {
84	  const ab = Buffer.from(a);
85	  const bb = Buffer.from(b);
86	  if (ab.length !== bb.length) return false;
87	  return timingSafeEqual(ab, bb);
88	}
89	
90	/**
91	 * Compute the PKCE S256 challenge: base64url(SHA-256(code_verifier)).
92	 * Identical algorithm to `sha256`, exposed under the PKCE name for clarity
93	 * at call sites.
94	 */
95	export function pkceS256Challenge(codeVerifier: string): string {
96	  return sha256(codeVerifier);
97	}
98	
99	// ─── argon2id helpers (client secrets) ──────────────────────────────────────
100	
101	function getPepper(): string {
102	  const pepper = process.env[PEPPER_ENV_VAR];
103	  if (!pepper || pepper.length < 16) {
104	    throw new Error(
105	      `${PEPPER_ENV_VAR} env var must be set to a high-entropy random value (base64, >= 16 chars)`,
106	    );
107	  }
108	  return pepper;
109	}
110	
111	/**
112	 * Dynamically import the `argon2` native module. Throws a clear error if the
113	 * package is not installed in the current environment (e.g. lint-only CI).
114	 */
115	async function loadArgon2(): Promise<typeof import('argon2')> {
116	  try {
117	    return (await import('argon2')) as typeof import('argon2');
118	  } catch (err) {
119	    const detail = err instanceof Error ? err.message : String(err);
120	    throw new Error(
121	      `argon2 module is not available — install 'argon2' to use client-secret hashing (cause: ${detail})`,
122	    );
123	  }
124	}
125	
126	/**
127	 * Hash a Zapier client secret using argon2id with the deployment pepper.
128	 * Store the returned PHC-encoded string in `oauth_clients.client_secret_hash`.
129	 */
130	export async function hashClientSecret(plaintext: string): Promise<string> {
131	  const argon2 = await loadArgon2();
132	  return argon2.hash(plaintext + getPepper(), {
133	    type: argon2.argon2id,
134	    memoryCost: ARGON2_PARAMS.memoryCost,
135	    timeCost: ARGON2_PARAMS.timeCost,
136	    parallelism: ARGON2_PARAMS.parallelism,
137	  });
138	}
139	
140	/**
141	 * Verify a presented client secret against the stored argon2id hash.
142	 * Returns false on any verification failure (including malformed hashes);
143	 * never throws to the caller, so timing of the failure path matches success.
144	 */
145	export async function verifyClientSecret(
146	  plaintext: string,
147	  storedHash: string,
148	): Promise<boolean> {
149	  let argon2: typeof import('argon2');
150	  try {
151	    argon2 = await loadArgon2();
152	  } catch (err) {
153	    console.error(
154	      '[oauth/crypto] argon2 load failed:',
155	      err instanceof Error ? err.message : String(err),
156	    );
157	    return false;
158	  }
159	  try {
160	    return await argon2.verify(storedHash, plaintext + getPepper());
161	  } catch (err) {
162	    console.error(
163	      '[oauth/crypto] verifyClientSecret failed:',
164	      err instanceof Error ? err.message : String(err),
165	    );
166	    return false;
167	  }
168	}
