1	/**
2	 * PKCE (RFC 7636) S256 verification for the Zapier OAuth surface.
3	 *
4	 * The `/api/oauth/authorize` endpoint stores `code_challenge` verbatim on the
5	 * authorization code row. `/api/oauth/token` then verifies the presented
6	 * `code_verifier` by recomputing the S256 challenge and constant-time
7	 * comparing against the stored value. Only S256 is accepted — the spec
8	 * (00-SHARED-CONTEXT.md "OAuth 2.0 specifics") and PKCE RFC 7636 §4.2 both
9	 * prohibit the `plain` method here.
10	 */
11	
12	import { constantTimeEquals, pkceS256Challenge } from './crypto';
13	
14	export type CodeChallengeMethod = 'S256';
15	
16	/**
17	 * Validate the `code_challenge` value against RFC 7636 §4.2:
18	 *   43–128 ASCII characters from the unreserved set `[A-Za-z0-9._~-]`.
19	 *
20	 * Returns `true` for a syntactically valid challenge; the caller still has to
21	 * verify it matches the presented verifier with `verifyPkceS256`.
22	 */
23	export function isValidCodeChallenge(challenge: string): boolean {
24	  if (typeof challenge !== 'string') return false;
25	  if (challenge.length < 43 || challenge.length > 128) return false;
26	  return /^[A-Za-z0-9._~-]+$/.test(challenge);
27	}
28	
29	/** Validate the `code_verifier` against RFC 7636 §4.1 (same charset, 43–128). */
30	export function isValidCodeVerifier(verifier: string): boolean {
31	  return isValidCodeChallenge(verifier);
32	}
33	
34	/**
35	 * Returns true iff the presented `codeVerifier` hashes to the stored
36	 * `codeChallenge` under the S256 method. Constant-time on the comparison
37	 * step so the failure-vs-success timing path cannot be used as an oracle.
38	 *
39	 * Any input that fails the syntactic checks returns false immediately —
40	 * callers translate that to an `invalid_grant` RFC 6749 error response.
41	 */
42	export function verifyPkceS256(
43	  codeVerifier: string,
44	  codeChallenge: string,
45	): boolean {
46	  if (!isValidCodeVerifier(codeVerifier)) return false;
47	  if (!isValidCodeChallenge(codeChallenge)) return false;
48	  const computed = pkceS256Challenge(codeVerifier);
49	  return constantTimeEquals(computed, codeChallenge);
50	}
51	
52	/** Accepts only `S256` (case-sensitive, per RFC 7636 §4.3). */
53	export function isSupportedChallengeMethod(
54	  method: string,
55	): method is CodeChallengeMethod {
56	  return method === 'S256';
57	}
