1	/**
2	 * Data-access interface for the Zapier OAuth handlers.
3	 *
4	 * Handlers in `./authorize.ts`, `./token.ts`, `./me.ts` take an `OAuthStore`
5	 * via dependency injection so they can be unit-tested without a database.
6	 * The db-backed implementation is in `./db-store.ts`; route.ts files compose
7	 * it and pass it to the handler.
8	 *
9	 * All `flightSchoolId` values are uuid strings. The spec's `org_id` is this
10	 * codebase's `flight_school_id`; the `/api/oauth/me` response still exposes
11	 * the tenant to Zapier as `school_id`.
12	 */
13	
14	import type { OAuthScope } from './types';
15	
16	export interface OAuthClientRow {
17	  clientId: string;
18	  clientSecretHash: string;
19	  clientName: string;
20	  redirectUris: string[];
21	  allowedScopes: string[];
22	  pkceRequired: boolean;
23	  revokedAt: Date | null;
24	}
25	
26	export interface OAuthAuthorizationCodeRow {
27	  id: string;
28	  codeHash: string;
29	  clientId: string;
30	  userId: string;
31	  flightSchoolId: string;
32	  redirectUri: string;
33	  scopes: OAuthScope[];
34	  codeChallenge: string;
35	  expiresAt: Date;
36	  usedAt: Date | null;
37	}
38	
39	export interface InsertAuthorizationCodeArgs {
40	  codeHash: string;
41	  clientId: string;
42	  userId: string;
43	  flightSchoolId: string;
44	  redirectUri: string;
45	  scopes: OAuthScope[];
46	  codeChallenge: string;
47	  expiresAt: Date;
48	}
49	
50	export interface OAuthAccessTokenRow {
51	  id: string;
52	  tokenHash: string;
53	  clientId: string;
54	  userId: string;
55	  flightSchoolId: string;
56	  scopes: OAuthScope[];
57	  expiresAt: Date;
58	  revokedAt: Date | null;
59	}
60	
61	export interface InsertAccessTokenArgs {
62	  tokenHash: string;
63	  clientId: string;
64	  userId: string;
65	  flightSchoolId: string;
66	  scopes: OAuthScope[];
67	  expiresAt: Date;
68	}
69	
70	export interface OAuthRefreshTokenRow {
71	  id: string;
72	  tokenHash: string;
73	  accessTokenId: string | null;
74	  clientId: string;
75	  userId: string;
76	  flightSchoolId: string;
77	  scopes: OAuthScope[];
78	  expiresAt: Date;
79	  revokedAt: Date | null;
80	  rotatedTo: string | null;
81	  /**
82	   * Insertion time. Used by supersede-on-reconnect as the ordering key so a
83	   * fresh authorization_code grant can revoke strictly-older live refresh
84	   * tokens for the same `(client_id, flight_school_id)` without racing its own
85	   * sibling. Backed by `oauth_refresh_tokens.created_at` (notNull, defaultNow).
86	   */
87	  createdAt: Date;
88	}
89	
90	export interface RevokePriorRefreshTokensArgs {
91	  clientId: string;
92	  flightSchoolId: string;
93	  /**
94	   * Exclusive upper bound. Only rows whose `created_at` is strictly less than
95	   * this are revoked — i.e. tokens minted before the in-flight grant's own
96	   * refresh token. The strictness is what prevents two concurrent reconnects
97	   * from revoking each other's freshly minted (equal-or-newer) token.
98	   */
99	  createdBefore: Date;
100	}
101	
102	export interface InsertRefreshTokenArgs {
103	  tokenHash: string;
104	  accessTokenId: string;
105	  clientId: string;
106	  userId: string;
107	  flightSchoolId: string;
108	  scopes: OAuthScope[];
109	  expiresAt: Date;
110	}
111	
112	export interface UserAndSchool {
113	  userId: string;
114	  userEmail: string;
115	  userName: string;
116	  flightSchoolId: string;
117	  flightSchoolName: string;
118	}
119	
120	export interface OAuthStore {
121	  // Clients
122	  findClientByClientId(clientId: string): Promise<OAuthClientRow | null>;
123	
124	  // Authorization codes
125	  insertAuthorizationCode(args: InsertAuthorizationCodeArgs): Promise<void>;
126	  findAuthorizationCodeByHash(
127	    hash: string,
128	  ): Promise<OAuthAuthorizationCodeRow | null>;
129	  markAuthorizationCodeUsed(id: string): Promise<void>;
130	
131	  // Access tokens
132	  insertAccessToken(args: InsertAccessTokenArgs): Promise<OAuthAccessTokenRow>;
133	  findAccessTokenByHash(hash: string): Promise<OAuthAccessTokenRow | null>;
134	  updateAccessTokenLastUsed(id: string, at: Date): Promise<void>;
135	  revokeAccessTokensForRefreshChain(refreshTokenId: string): Promise<void>;
136	
137	  // Refresh tokens
138	  insertRefreshToken(
139	    args: InsertRefreshTokenArgs,
140	  ): Promise<OAuthRefreshTokenRow>;
141	  findRefreshTokenByHash(hash: string): Promise<OAuthRefreshTokenRow | null>;
142	  /**
143	   * Mark `oldId` rotated to `newId`. Conditional on the row not already
144	   * being rotated — returns false when a concurrent refresh won the race,
145	   * in which case the caller must NOT treat the loser as a replay.
146	   */
147	  rotateRefreshToken(oldId: string, newId: string): Promise<boolean>;
148	  /**
149	   * Supersede-on-reconnect hygiene. Revoke the LIVE (`revoked_at IS NULL`)
150	   * refresh tokens for a `(client_id, flight_school_id)` pair created strictly
151	   * before `createdBefore`, and return how many were revoked.
152	   *
153	   * Called once after an `authorization_code` grant mints a new pair, so a
154	   * re-connect doesn't accumulate orphaned 30-day refresh credentials. It is
155	   * "last-reconnect-wins": because the bound is the in-flight grant's OWN
156	   * refresh `created_at` and the comparison is strict, neither of two
157	   * concurrent reconnects can revoke its own or the other's newer token — at
158	   * worst the loser leaves one extra orphan that 30-day expiry reaps. Scoped
159	   * on BOTH `client_id` AND `flight_school_id`; never cross-tenant. Best
160	   * effort: the caller swallows failures, so an implementation may throw.
161	   */
162	  revokePriorRefreshTokens(args: RevokePriorRefreshTokensArgs): Promise<number>;
163	
164	  // User + school
165	  findUserAndSchool(appUserId: string): Promise<UserAndSchool | null>;
166	
167	  /**
168	   * Resolve a BetterAuth `authUser` (text id, email-keyed multi-tenant user
169	   * lookup) to the app-level `users.id` UUID + tenancy. Used by the
170	   * authorize endpoint to map the logged-in BetterAuth session to the
171	   * domain user row that owns the consent grant.
172	   */
173	  resolveAppUserFromAuthEmail(email: string): Promise<UserAndSchool | null>;
174	}
