1	/**
2	 * `/api/oauth/me` handler logic.
3	 *
4	 * Returns the 5-field canonical JSON shape from 00-SHARED-CONTEXT.md. The
5	 * tenant is exposed to Zapier as `school_id` — the underlying column is
6	 * `flight_school_id`.
7	 */
8	
9	import { requireIntegrationApiEnabled } from '@/server/integrations/zapier/feature-flag';
10	import { sha256 } from './crypto';
11	import { OAuthError } from './errors';
12	import type { OAuthStore } from './store';
13	import type { OAuthMeResponse, OAuthScope } from './types';
14	
15	export interface HandleMeArgs {
16	  /** The Bearer token plaintext, extracted from `Authorization: Bearer ...`. */
17	  bearerToken: string | null;
18	  store: OAuthStore;
19	  now?: () => Date;
20	}
21	
22	export type MeResult =
23	  | { kind: 'success'; response: OAuthMeResponse }
24	  | { kind: 'error'; error: OAuthError };
25	
26	export async function handleMe(args: HandleMeArgs): Promise<MeResult> {
27	  requireIntegrationApiEnabled();
28	
29	  if (!args.bearerToken) {
30	    return {
31	      kind: 'error',
32	      error: new OAuthError(
33	        'invalid_request',
34	        'missing or malformed Bearer token',
35	      ),
36	    };
37	  }
38	
39	  const hash = sha256(args.bearerToken);
40	  const tokenRow = await args.store.findAccessTokenByHash(hash);
41	  if (!tokenRow) {
42	    return {
43	      kind: 'error',
44	      error: new OAuthError('invalid_grant', 'access token not found'),
45	    };
46	  }
47	  if (tokenRow.revokedAt) {
48	    return {
49	      kind: 'error',
50	      error: new OAuthError('invalid_grant', 'access token revoked'),
51	    };
52	  }
53	
54	  const now = (args.now ?? (() => new Date()))();
55	  if (tokenRow.expiresAt.getTime() <= now.getTime()) {
56	    return {
57	      kind: 'error',
58	      error: new OAuthError('invalid_grant', 'access token expired'),
59	    };
60	  }
61	
62	  const user = await args.store.findUserAndSchool(tokenRow.userId);
63	  if (!user) {
64	    return {
65	      kind: 'error',
66	      error: new OAuthError(
67	        'invalid_grant',
68	        'access token has no associated user',
69	      ),
70	    };
71	  }
72	
73	  // Best-effort last-used update — failure here must not block the response.
74	  try {
75	    await args.store.updateAccessTokenLastUsed(tokenRow.id, now);
76	  } catch {
77	    /* swallow — log site is the route boundary */
78	  }
79	
80	  return {
81	    kind: 'success',
82	    response: {
83	      school_id: user.flightSchoolId,
84	      school_name: user.flightSchoolName,
85	      user_email: user.userEmail,
86	      user_name: user.userName,
87	      scopes: tokenRow.scopes as OAuthScope[],
88	    },
89	  };
90	}
