1	/**
2	 * Mints OAuth access + refresh token pairs.
3	 *
4	 * Used by `/api/oauth/token` for both the `authorization_code` grant and the
5	 * `refresh_token` grant. Plaintext tokens are returned exactly once to the
6	 * caller; only their SHA-256 hashes are persisted (see crypto.ts).
7	 *
8	 * TTLs come from `./types.ts`:
9	 *   - access  : 3600s   (ACCESS_TOKEN_TTL_SECONDS)
10	 *   - refresh : 2592000s (REFRESH_TOKEN_TTL_SECONDS, 30 days)
11	 */
12	
13	import { generateOpaqueToken } from './crypto';
14	import type { OAuthStore } from './store';
15	import {
16	  ACCESS_TOKEN_TTL_SECONDS,
17	  type OAuthScope,
18	  REFRESH_TOKEN_TTL_SECONDS,
19	} from './types';
20	
21	export interface MintTokenPairArgs {
22	  store: OAuthStore;
23	  clientId: string;
24	  userId: string;
25	  flightSchoolId: string;
26	  scopes: OAuthScope[];
27	  /** Optional clock override for deterministic tests. */
28	  now?: () => Date;
29	}
30	
31	export interface MintedTokenPair {
32	  accessToken: string;
33	  refreshToken: string;
34	  accessTokenId: string;
35	  refreshTokenId: string;
36	  expiresIn: number;
37	  /**
38	   * `created_at` of the newly inserted refresh-token row, as assigned by the
39	   * store (the DB's `defaultNow()` in prod). Supersede-on-reconnect uses this
40	   * as the exclusive upper bound when revoking older live refresh tokens.
41	   */
42	  refreshCreatedAt: Date;
43	}
44	
45	/**
46	 * Mint a new access + refresh token pair and persist hashes. The plaintext
47	 * values come back in the returned object — the caller writes them into the
48	 * OAuth token response and never persists them again.
49	 */
50	export async function mintTokenPair(
51	  args: MintTokenPairArgs,
52	): Promise<MintedTokenPair> {
53	  const now = (args.now ?? (() => new Date()))();
54	
55	  const access = generateOpaqueToken();
56	  const refresh = generateOpaqueToken();
57	
58	  const accessExpiresAt = new Date(
59	    now.getTime() + ACCESS_TOKEN_TTL_SECONDS * 1000,
60	  );
61	  const refreshExpiresAt = new Date(
62	    now.getTime() + REFRESH_TOKEN_TTL_SECONDS * 1000,
63	  );
64	
65	  const accessRow = await args.store.insertAccessToken({
66	    tokenHash: access.hash,
67	    clientId: args.clientId,
68	    userId: args.userId,
69	    flightSchoolId: args.flightSchoolId,
70	    scopes: args.scopes,
71	    expiresAt: accessExpiresAt,
72	  });
73	
74	  const refreshRow = await args.store.insertRefreshToken({
75	    tokenHash: refresh.hash,
76	    accessTokenId: accessRow.id,
77	    clientId: args.clientId,
78	    userId: args.userId,
79	    flightSchoolId: args.flightSchoolId,
80	    scopes: args.scopes,
81	    expiresAt: refreshExpiresAt,
82	  });
83	
84	  return {
85	    accessToken: access.plaintext,
