1	/**
2	 * Wave 6 W6-2 — runtime action gate for `/api/v1/*` write endpoints.
3	 *
4	 * The Zapier `/api/v1/*` surface routes through generic handlers
5	 * (`create-handler.ts`, `delete-handler.ts`) that already gate on the
6	 * required OAuth scope. W6-2 adds a SECOND gate after the scope check:
7	 *
8	 *   1. Look up the action `key` for the request `(method, path)` by
9	 *      matching against `ACTION_REGISTRY` (the in-code source of truth
10	 *      from `src/server/oauth/action-registry.ts`).
11	 *   2. If no key matches, the action is unregistered — that is a
12	 *      registry-discipline gap (every write endpoint MUST have a
13	 *      registry entry). We FAIL OPEN to avoid breaking deploys; the CI
14	 *      parity test (`tests/unit/server/api/routers/action-catalog-
15	 *      discovery.test.ts`) catches the gap separately.
16	 *   3. If a key matches, call `getAction(key, { store, flightSchoolId })`
17	 *      to resolve overrides. When the merged result yields
18	 *      `enabled_globally === false` (global kill switch or per-school
19	 *      override flipping the same flag), or when `status === 'archived'`
20	 *      (lifecycle kill switch), the gate returns a 403
21	 *      `action_disabled` response.
22	 *
23	 * Why a separate gate (not just `requireScope`):
24	 *   The scope check governs WHICH tenant capabilities a token can call;
25	 *   the action gate governs WHETHER a capability is currently exposed
26	 *   AT ALL on the platform. Two distinct authorization questions, two
27	 *   distinct decision points. A misbehaving downstream consumer might
28	 *   need an action disabled (e.g., `crm_contacts:create` spamming
29	 *   placeholder rows) without touching the scope itself.
30	 *
31	 * Telemetry: callers (`create-handler.ts`, `delete-handler.ts`) MUST
32	 * write an audit row when this gate fires — the existing audit writer
33	 * already does this for the scope check; the same envelope works for
34	 * the action gate (status 403, endpoint path, status-code 403).
35	 */
36	
37	import { ACTION_REGISTRY } from '@/server/oauth/action-registry';
38	import {
39	  type ActionOverrideStore,
40	  type ResolvedAction,
41	  getAction,
42	} from '@/server/oauth/action-registry';
43	
44	/**
45	 * Outcome of an action-gate check.
46	 *
47	 *   - `allow`: the action is enabled (no override or override permits).
48	 *     Caller may proceed.
49	 *   - `not-registered`: no `ACTION_REGISTRY` entry matched the request.
50	 *     The gate fails open — the caller proceeds and the missing entry
51	 *     is caught by the discovery parity test.
52	 *   - `disabled`: a registered action whose merged view is currently
53	 *     disabled. The HTTP layer maps to `403 { error: 'action_disabled' }`.
54	 *     The `reason` discriminates global / per-school / archived for the
55	 *     error envelope.
56	 */
57	export type ActionGateResult =
58	  | { kind: 'allow'; action: ResolvedAction }
59	  | { kind: 'not-registered' }
60	  | {
61	      kind: 'disabled';
62	      action: ResolvedAction;
63	      reason: 'global' | 'school' | 'archived';
64	    };
65	
66	/**
67	 * Resolve the action key for `(method, path)` by linear scan over
68	 * `ACTION_REGISTRY`. The registry is small (≈ 15 entries today) and the
69	 * scan is per-request — re-cost is negligible compared to the DB lookup
70	 * that follows.
71	 *
72	 * Path matching is parameter-aware: `/api/v1/invoices/{id}/pay` in the
73	 * registry matches `/api/v1/invoices/abc-123/pay` at runtime. The
74	 * matcher replaces every `{name}` token with a non-slash regex segment.
75	 *
76	 * Returns `null` when no registry entry matches.
77	 */
78	export function resolveActionKey(method: string, path: string): string | null {
79	  const methodUpper = method.toUpperCase();
80	  for (const entry of Object.values(ACTION_REGISTRY)) {
81	    if (entry.method !== methodUpper) continue;
82	    if (pathMatches(entry.path, path)) {
83	      return entry.key;
84	    }
85	  }
86	  return null;
87	}
88	
89	function pathMatches(template: string, actual: string): boolean {
90	  if (template === actual) return true;
91	  // Replace `{name}` segments with a non-slash regex chunk. Anchored.
92	  const regexSrc = `^${template
93	    .split('/')
94	    .map((segment) => {
95	      if (segment.startsWith('{') && segment.endsWith('}')) {
96	        return '[^/]+';
97	      }
98	      // Escape regex metacharacters present in literal segments.
99	      return segment.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
100	    })
101	    .join('/')}$`;
102	  return new RegExp(regexSrc).test(actual);
103	}
104	
105	/**
106	 * Evaluate the action gate for a request.
107	 *
108	 * @param method   HTTP method (`POST` | `PATCH` | `PUT` | `DELETE`).
109	 * @param path     Concrete request path, e.g. `/api/v1/students` or
110	 *                 `/api/v1/invoices/abc-123/pay`.
111	 * @param flightSchoolId  Tenant scope from the verified OAuth token. Required
112	 *                 for the per-school override read. When undefined, only the
113	 *                 global override is consulted.
114	 * @param store    Override store. Injectable for tests; production passes
115	 *                 the DB-backed store.
116	 */
117	export async function checkActionGate(args: {
118	  method: string;
119	  path: string;
120	  flightSchoolId?: string;
121	  store: ActionOverrideStore;
122	}): Promise<ActionGateResult> {
123	  const key = resolveActionKey(args.method, args.path);
124	  if (!key) return { kind: 'not-registered' };
125	  const action = await getAction(key, {
126	    store: args.store,
127	    flightSchoolId: args.flightSchoolId,
128	  });
129	  if (!action) return { kind: 'not-registered' };
130	
131	  if (action.status === 'archived') {
132	    return { kind: 'disabled', action, reason: 'archived' };
133	  }
134	  if (!action.enabled_globally) {
135	    // If the per-school override flipped it false, `source` will mark
136	    // enabled_globally as 'override'; without a flightSchoolId we can't
137	    // tell which layer set it. The discriminator is best-effort here —
138	    // the response envelope just needs to be correctly 403'd.
139	    const reason: 'school' | 'global' =
140	      args.flightSchoolId && action.source.enabled_globally === 'override'
141	        ? 'school'
142	        : 'global';
143	    return { kind: 'disabled', action, reason };
144	  }
145	  return { kind: 'allow', action };
146	}
