1	/**
2	 * Scope constants + parser helpers for the Zapier OAuth surface.
3	 *
4	 * The scope type itself and `isScopeSubset` live in `./types.ts` (Stream 0).
5	 * This module narrows the public surface to the operations Stream 1 needs:
6	 * parsing the wire-format scope string and validating an incoming list
7	 * against a client's `allowed_scopes`.
8	 *
9	 * See: prompts/zapier-wave-1/00-SHARED-CONTEXT.md ("Scope definitions").
10	 */
11	
12	import { OAUTH_SCOPES, type OAuthScope, isOAuthScope } from './types';
13	
14	export { OAUTH_SCOPES, type OAuthScope, isOAuthScope };
15	
16	/**
17	 * Parse the RFC 6749 §3.3 scope string ("space-delimited") into a deduped
18	 * list. Throws `InvalidScopeError` if any token isn't a recognised
19	 * `OAuthScope`. Returns `[]` for an empty / whitespace-only input — the
20	 * authorize handler treats that as "no scope requested" and rejects upstream.
21	 */
22	export function parseScopeString(scope: string): OAuthScope[] {
23	  if (typeof scope !== 'string' || scope.trim().length === 0) return [];
24	  const tokens = scope.trim().split(/\s+/);
25	  const out: OAuthScope[] = [];
26	  const seen = new Set<string>();
27	  for (const t of tokens) {
28	    if (seen.has(t)) continue;
29	    if (!isOAuthScope(t)) {
30	      throw new InvalidScopeError(`unknown scope: ${t}`);
31	    }
32	    seen.add(t);
33	    out.push(t);
34	  }
35	  return out;
36	}
37	
38	/** Encode a scope list back into the wire-format ("read:students write:students"). */
39	export function formatScopeString(scopes: readonly OAuthScope[]): string {
40	  return scopes.join(' ');
41	}
42	
43	/**
44	 * Returns true iff every requested scope appears in the client's
45	 * `allowed_scopes`. An empty `requested` is treated as not a subset — we
46	 * require at least one scope per RFC 6749 §3.3.
47	 */
48	export function isAllowedSubset(
49	  requested: readonly OAuthScope[],
50	  allowed: readonly string[],
51	): boolean {
52	  if (requested.length === 0) return false;
53	  const set = new Set(allowed);
54	  return requested.every((s) => set.has(s));
55	}
56	
57	/** Thrown when a requested scope isn't part of `OAUTH_SCOPES`. */
58	export class InvalidScopeError extends Error {
59	  constructor(message: string) {
60	    super(message);
61	    this.name = 'InvalidScopeError';
62	  }
63	}
