1	/**
2	 * RFC 6749 §5.2 error envelope, surfaced by `/api/oauth/token` and
3	 * `/api/oauth/authorize` when the request itself is invalid (vs. the user
4	 * denying consent, which is a redirect).
5	 *
6	 * Throw `OAuthError` from handler internals; the route boundary translates
7	 * to `{ error, error_description }` JSON with the correct HTTP status.
8	 */
9	
10	import type { OAuthErrorCode } from './types';
11	
12	/** Default HTTP status per RFC 6749 §5.2. */
13	const STATUS_BY_CODE: Record<OAuthErrorCode, number> = {
14	  invalid_request: 400,
15	  invalid_grant: 400,
16	  invalid_scope: 400,
17	  unsupported_grant_type: 400,
18	  invalid_client: 401,
19	  unauthorized_client: 403,
20	  access_denied: 400,
21	  server_error: 500,
22	};
23	
24	export class OAuthError extends Error {
25	  readonly code: OAuthErrorCode;
26	  readonly status: number;
27	  readonly description?: string;
28	
29	  constructor(
30	    code: OAuthErrorCode,
31	    description?: string,
32	    statusOverride?: number,
33	  ) {
34	    super(description ?? code);
35	    this.name = 'OAuthError';
36	    this.code = code;
37	    this.status = statusOverride ?? STATUS_BY_CODE[code];
38	    this.description = description;
39	  }
40	
41	  toJSON(): { error: OAuthErrorCode; error_description?: string } {
42	    return this.description
43	      ? { error: this.code, error_description: this.description }
44	      : { error: this.code };
45	  }
46	}
