1	/**
2	 * Resolve the target Better-Auth user identified by `targetUserId` (an
3	 * `authUser.id`), but ONLY when that user belongs to a school the caller may
4	 * administer. The tenant check for an admin mutating another user's authUser
5	 * row: `requireAdmin()` gates role, not tenant.
6	 *
7	 * The target's email is looked up FROM `targetUserId` here — never taken from a
8	 * caller-supplied value — so the org check is always performed against the exact
9	 * row the caller is about to write. (An earlier version accepted the request
10	 * email directly, which let a caller pass `userId=<victim>` + `email=<same-org
11	 * accomplice>` and pass the check while the write targeted the victim.)
12	 *
13	 * authUser has no flightSchoolId (and authUser.id ≠ users.id — bridged only by
14	 * email, same distinction resolveAppUserId() documents), so the target is
15	 * matched by email against the caller's org. Membership is checked in BOTH app
16	 * tables, because either one alone under-reports it:
17	 *   1. `users`, via resolveSchoolScopedUser — correct for multi-school emails (a
18	 *      plain resolveOrgIdFromEmail + compare would use the target's PRIMARY
19	 *      school and wrongly reject a legitimate same-school edit).
20	 *   2. `team_members`, via resolveSchoolScopedTeamMember — Location Admins and
21	 *      freshly-invited staff have no `users` row at all (helpers.ts:207), so a
22	 *      users-only check 403s the Team page's own name syncs. This mirrors the
23	 *      fallback resolveOrgIdFromEmail already applies on the caller side.
24	 * Both lookups are scoped to the caller's org, so neither can match a foreign
25	 * school's row.
26	 *
27	 * super_admins are platform-wide and belong to the platform school, not to any
28	 * customer school, so both org-scoped lookups miss whenever they manage another
29	 * school without an X-Managed-School-Id header (deep links, and callers that
30	 * simply don't send it). They get the same explicit bypass verifyLocationAccess
31	 * applies (helpers.ts:168), resolved against the target's own school.
32	 *
33	 * Returns null — which callers treat as "forbidden" (fail closed) — when the
34	 * caller's org can't be resolved, the target's email can't be found, or the
35	 * target has no membership in the caller's org. Reusable by any route that
36	 * writes another user's authUser row.
37	 */
38	import { db } from '@/lib/db';
39	import * as schema from '@/lib/schema';
40	import {
41	  resolveOrgIdFromEmail,
42	  resolveOrgIdFromSession,
43	} from '@/server/helpers';
44	import type { AuthUser } from '@/server/middleware/auth';
45	import { eq } from 'drizzle-orm';
46	import type { Context } from 'hono';
47	import { resolveSchoolScopedTeamMember } from './resolve-school-scoped-team-member';
48	import {
49	  type SchoolScopedUser,
50	  resolveSchoolScopedUser,
51	} from './resolve-school-scoped-user';
52	
53	export interface SameOrgAuthUserTarget {
54	  /**
55	   * The school the target was matched in: the caller's own org, or — for a
56	   * super_admin falling through the platform-wide bypass — the target's school.
57	   */
58	  orgId: string;
59	  /**
60	   * The target's app `users` row in that school. Null when the target exists
61	   * only in `team_members` (Location Admins / freshly-invited staff), which is
62	   * still a valid same-school match — callers must not read this as "denied";
63	   * a null RESULT (not a null `user`) is the denial.
64	   */
65	  user: SchoolScopedUser | null;
66	}
67	
68	export async function resolveSameOrgAuthUser(
69	  c: Context,
70	  authUser: AuthUser,
71	  targetUserId: string,
72	): Promise<SameOrgAuthUserTarget | null> {
73	  const isSuperAdmin = authUser.role === 'super_admin';
74	  const callerOrgId = await resolveOrgIdFromSession(authUser, c);
75	  if (!callerOrgId && !isSuperAdmin) return null;
76	
77	  const [row] = await db
78	    .select({ email: schema.authUser.email })
79	    .from(schema.authUser)
80	    .where(eq(schema.authUser.id, targetUserId))
81	    .limit(1);
82	  const email = row?.email ?? null;
83	  if (!email) return null;
84	
85	  if (callerOrgId) {
86	    const user = await resolveSchoolScopedUser(email, callerOrgId);
87	    if (user) return { orgId: callerOrgId, user };
88	
89	    const member = await resolveSchoolScopedTeamMember(email, callerOrgId);
90	    if (member) return { orgId: callerOrgId, user: null };
91	  }
92	
93	  if (!isSuperAdmin) return null;
94	
95	  // Platform-wide bypass: the super_admin isn't a member of the school they're
96	  // managing, so the scoped lookups above cannot match. Resolving the org from
97	  // the target (again, derived from targetUserId) widens nothing beyond the
98	  // reach super_admins already have, and still fails closed for a target with
99	  // no membership anywhere.
100	  const targetOrgId = await resolveOrgIdFromEmail(email);
101	  if (!targetOrgId) return null;
102	  return {
103	    orgId: targetOrgId,
104	    user: await resolveSchoolScopedUser(email, targetOrgId),
105	  };
106	}
